import { supportsFetchAppEmbeddedKey } from './supportsFetchAppEmbeddedKey';
import { fetchViaFrame } from './fetchViaFrame';
import { fetchViaHost } from './fetchViaHost';
let selectedStripeApiFetch = null;
export const selectPreferredStripeApiFetch = async () => {
    if (!selectedStripeApiFetch) {
        selectedStripeApiFetch = (await supportsFetchAppEmbeddedKey())
            ? fetchViaFrame
            : fetchViaHost;
    }
    return selectedStripeApiFetch;
};
